requests.utils.unquote_header_value:
def unquote_header_value(value, is_filename=False):
    """Unquotes a header value.  (Reversal of :func:`quote_header_value`).
    This does not use the real unquoting but what browsers are actually
    using for quoting.

    :param value: the header value to unquote.
    :rtype: str
    """
    if (value and value[0] == value[-1] == '"'):
        value = value[1:-1]
        if (not is_filename or value[:2] != '\\\\'):
            return value.replace('\\\\', '\\').replace('\\"', '"')
    return value

requests.utils.proxy_bypass:
def proxy_bypass(host):
    """Return True, if the host should be bypassed.

        Checks proxy settings gathered from the environment, if specified,
        or the registry.
        """
    if getproxies_environment():
        return proxy_bypass_environment(host)
    else:
        return proxy_bypass_registry(host)

requests.utils.proxy_bypass_registry:
def proxy_bypass_registry(host):
    try:
        import winreg
    except ImportError:
        return False
    try:
        internetSettings = winreg.OpenKey(winreg.HKEY_CURRENT_USER, 'Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings')
        proxyEnable = int(winreg.QueryValueEx(internetSettings, 'ProxyEnable')[0])
        proxyOverride = winreg.QueryValueEx(internetSettings, 'ProxyOverride')[0]
    except (OSError, ValueError):
        return False
    if (not proxyEnable or not proxyOverride):
        return False
    proxyOverride = proxyOverride.split(';')
    proxyOverride = filter(None, proxyOverride)
    for test in proxyOverride:
        if test == '<local>':
            if '.' not in host:
                return True
        test = test.replace('.', '\\.')
        test = test.replace('*', '.*')
        test = test.replace('?', '.')
        if re.match(test, host, re.I):
            return True
    return False

charset_normalizer.cd.get_target_feature:
@lru_cache(maxsize=LANGUAGE_SUPPORTED_COUNT)
def get_target_features(language: str) -> tuple[(bool, bool)]:
    """
    Determine main aspects from a supported language if it contains accents and if is pure Latin.
    """
    target_have_accents: bool = False
    target_pure_latin: bool = True
    for character in FREQUENCIES[language]:
        codepoint = ord(character)
        info = (_ASCII_CHAR_INFO[codepoint] if codepoint < 128 else _char_info(character))
        if (not target_have_accents and info.accentuated):
            target_have_accents = True
        if (target_pure_latin and not info.latin):
            target_pure_latin = False
    return (target_have_accents, target_pure_latin)

charset_normalizer.utils.is_emoticon:
def is_emoticon(character: str) -> bool:
    character_range: str | None = unicode_range(character)
    if character_range is None:
        return False
    return ('Emoticons' in character_range or 'Pictographs' in character_range)

charset_normalizer.utils.cp_similarity:
def cp_similarity(iana_name_a: str, iana_name_b: str) -> float:
    if (is_multi_byte_encoding(iana_name_a) or is_multi_byte_encoding(iana_name_b)):
        return 0.0
    decoder_a = importlib.import_module(f'encodings.{iana_name_a}').IncrementalDecoder
    decoder_b = importlib.import_module(f'encodings.{iana_name_b}').IncrementalDecoder
    id_a: IncrementalDecoder = decoder_a(errors='ignore')
    id_b: IncrementalDecoder = decoder_b(errors='ignore')
    character_match_count: int = 0
    for i in range(256):
        to_be_decoded: bytes = bytes([i])
        if id_a.decode(to_be_decoded) == id_b.decode(to_be_decoded):
            character_match_count += 1
    return character_match_count / 256

urllib3.util.ssl_._is_has_never_check_co:
def _is_has_never_check_common_name_reliable(openssl_version: str, openssl_version_number: int, implementation_name: str, version_info: _TYPE_VERSION_INFO, pypy_version_info: _TYPE_VERSION_INFO | None) -> bool:
    is_openssl = openssl_version.startswith('OpenSSL ')
    is_openssl_issue_14579_fixed = openssl_version_number >= 269488335
    return (is_openssl and ((is_openssl_issue_14579_fixed or _is_bpo_43522_fixed(implementation_name, version_info, pypy_version_info))))

urllib3.util.ssl_._is_bpo_43522_fixed:
def _is_bpo_43522_fixed(implementation_name: str, version_info: _TYPE_VERSION_INFO, pypy_version_info: _TYPE_VERSION_INFO | None) -> bool:
    """Return True for CPython 3.9.3+ or 3.10+ and PyPy 7.3.8+ where
    setting SSLContext.hostname_checks_common_name to False works.

    Outside of CPython and PyPy we don't know which implementations work
    or not so we conservatively use our hostname matching as we know that works
    on all implementations.

    https://github.com/urllib3/urllib3/issues/2192#issuecomment-821832963
    https://foss.heptapod.net/pypy/pypy/-/issues/3539
    """
    if implementation_name == 'pypy':
        return pypy_version_info >= (7, 3, 8)
    elif implementation_name == 'cpython':
        major_minor = version_info[:2]
        micro = version_info[2]
        return ((major_minor == (3, 9) and micro >= 3) or major_minor >= (3, 10))
    else:
        return False

urllib3.util.util.to_bytes:
def to_bytes(x: str | bytes, encoding: str | None = None, errors: str | None = None) -> bytes:
    if isinstance(x, bytes):
        return x
    elif not isinstance(x, str):
        raise TypeError(f'not expecting type {type(x).__name__}')
    if (encoding or errors):
        return x.encode((encoding or 'utf-8'), errors=(errors or 'strict'))
    return x.encode()
